function buildSourceRow(list){
  const items = list.slice(0, 6).map((r, idx) => {
    const n = idx + 1;
    if (r.kind === "file" || !r.link){
      return `<span class="file-source">[${n}] ${esc(r.title)}</span>`;
    }
    return `<a href="${esc(r.link)}" target="_blank" rel="noopener">[${n}]《${esc(r.title)}》</a>`;
  }).join("");
  return `<div class="src"><span>出处</span>${items}</div>`;
}

