function render(data, quiet){
  noteServerRestart(data.started_at);
  const rs = data.results || [];
  lastRender = {data, quiet};
  const showVerdict = settings.features.verdict;
  if (!quiet){
    if (showVerdict){
      const verdict = kind === "file" ? {cls:"",text:`检索到 ${rs.length} 份候选文件，请核对内容与版本。`} : verdictFor(rs);
      statusEl.className = verdict.cls;
      statusEl.textContent = verdict.text;
    }else{
      statusEl.className = "";
      statusEl.textContent = "";
    }
  }
  if (!rs.length){
    if (!quiet && showVerdict){
      statusEl.className = "no";
      statusEl.textContent = kind === "file" ? "未检索到相关文件。" : "未检索到相关资料。";
    }
    resultsEl.innerHTML = `<div class="empty">没搜到。<br>换个说法试试，或者切一个筛选。</div>`;
    return;
  }
  resultsEl.innerHTML = "";
  rs.forEach((r, i) => {
    r.rel = Math.round(Math.min(Number(r.score || 0), 1) * 100);
    resultsEl.appendChild(renderCard(r, i));
  });
}

function cardExcerpt(text){
  const hits=terms.filter(t=>t.length>=2).map(t=>text.toLowerCase().indexOf(t.toLowerCase())).filter(p=>p>=0);
  if(!hits.length) return text;
  const pos=Math.min(...hits);
  let start=Math.max(text.lastIndexOf("\n",pos),text.lastIndexOf("。",pos),text.lastIndexOf("；",pos))+1;
  if(start<0 || start>pos) start=0;
  const end=Math.min(text.length,Math.max(start+150,pos+50));
  return (start>0?"…":"")+text.slice(start,end).trim()+(end<text.length?"…":"");
}
